    ['“చౌక” అంటే?', 'తక్కువ ధర', 'ఎక్కువ ధర', 'బజారు', 'మోసం'],
    ['“రాజు” పదానికి వికృతి?', 'ఱేడు', 'రాయలు', 'రాతిరి', 'మొగము'],
